CREATE TABLE profiles(id TEXT PRIMARY KEY, created REAL NOT NULL);
CREATE TABLE profile_versions(id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), parent_id TEXT REFERENCES profile_versions(id), payload TEXT NOT NULL CHECK(json_valid(payload)), provenance TEXT NOT NULL, created REAL NOT NULL);
CREATE TRIGGER immutable_profiles BEFORE UPDATE ON profile_versions BEGIN SELECT RAISE(ABORT,'profile versions are immutable'); END;
CREATE TABLE profile_records(id TEXT PRIMARY KEY, version_id TEXT NOT NULL REFERENCES profile_versions(id), kind TEXT NOT NULL, record_key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), UNIQUE(version_id,kind,record_key));
CREATE TABLE documents(id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('cv','transcript','cover_letter','writing_sample','other')), path TEXT NOT NULL, sha256 TEXT NOT NULL, version INTEGER NOT NULL, approved INTEGER NOT NULL CHECK(approved IN (0,1)), profile_id TEXT REFERENCES profiles(id), applicability TEXT NOT NULL CHECK(json_valid(applicability)), mime TEXT NOT NULL, size INTEGER NOT NULL CHECK(size>=0), created REAL NOT NULL, UNIQUE(path,sha256));
CREATE TABLE employers(id TEXT PRIMARY KEY, name TEXT NOT NULL, tenant TEXT NOT NULL);
CREATE TABLE vacancies(id TEXT PRIMARY KEY, employer_id TEXT NOT NULL REFERENCES employers(id), role TEXT NOT NULL, identity TEXT NOT NULL UNIQUE, url TEXT NOT NULL, cycle TEXT, eligibility TEXT NOT NULL DEFAULT 'unknown', metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata)));
CREATE TABLE vacancy_sources(id TEXT PRIMARY KEY,vacancy_id TEXT REFERENCES vacancies(id),url TEXT NOT NULL,checked REAL NOT NULL,evidence TEXT NOT NULL CHECK(json_valid(evidence)));
CREATE TABLE runs(id TEXT PRIMARY KEY, plan TEXT NOT NULL CHECK(json_valid(plan)), status TEXT NOT NULL CHECK(status IN ('ACTIVE','PAUSED','STOPPED','DONE')), created REAL NOT NULL);
CREATE TABLE grants(id TEXT PRIMARY KEY, run_id TEXT NOT NULL UNIQUE REFERENCES runs(id), expires REAL NOT NULL, revoked INTEGER NOT NULL DEFAULT 0 CHECK(revoked IN (0,1)), provenance TEXT NOT NULL);
CREATE TABLE batches(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(id),requested INTEGER NOT NULL CHECK(requested BETWEEN 1 AND 10));
CREATE TABLE applications(id TEXT PRIMARY KEY, vacancy_id TEXT NOT NULL REFERENCES vacancies(id), profile_id TEXT NOT NULL REFERENCES profiles(id), account TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('QUEUED','ELIGIBILITY_UNVERIFIED','ELIGIBLE','NEEDS_INFORMATION','NEEDS_AUTHENTICATION','EMAIL_PENDING','FILLING','PAGE_FILLED','INCOMPLETE','REVIEW_READY','SUBMITTING','SUBMISSION_UNCONFIRMED','SUBMITTED_CONFIRMED','SUBMITTED_USER_REPORTED','POLICY_BLOCKED','UNSUPPORTED','CANCELLED','FAILED_RETRYABLE')), owner TEXT, fence INTEGER NOT NULL DEFAULT 0, lease_until REAL, updated REAL NOT NULL, detail TEXT NOT NULL DEFAULT '', UNIQUE(vacancy_id,profile_id));
CREATE TABLE run_applications(run_id TEXT NOT NULL REFERENCES runs(id),application_id TEXT NOT NULL REFERENCES applications(id),profile_version TEXT NOT NULL REFERENCES profile_versions(id),target TEXT NOT NULL CHECK(json_valid(target)),PRIMARY KEY(run_id,application_id));
CREATE TABLE application_documents(application_id TEXT NOT NULL REFERENCES applications(id),document_id TEXT NOT NULL REFERENCES documents(id),PRIMARY KEY(application_id,document_id));
CREATE TABLE reservations(slot INTEGER PRIMARY KEY CHECK(slot BETWEEN 1 AND 10), application_id TEXT NOT NULL UNIQUE REFERENCES applications(id),owner TEXT NOT NULL,fence INTEGER NOT NULL,expires REAL NOT NULL);
CREATE TABLE account_locks(account TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES applications(id),owner TEXT NOT NULL,fence INTEGER NOT NULL);
CREATE TABLE sessions(application_id TEXT PRIMARY KEY REFERENCES applications(id),tab_id TEXT NOT NULL,context_id TEXT NOT NULL,retained INTEGER NOT NULL DEFAULT 1 CHECK(retained IN (0,1)));
CREATE TABLE tasks(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(id),application_id TEXT NOT NULL REFERENCES applications(id),kind TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('QUEUED','RUNNING','PARKED','DONE','CANCELLED')),attempts INTEGER NOT NULL DEFAULT 0,not_before REAL NOT NULL DEFAULT 0,UNIQUE(run_id,application_id,kind));
CREATE INDEX tasks_ready ON tasks(status,not_before);
CREATE TABLE task_dependencies(task_id TEXT NOT NULL REFERENCES tasks(id),depends_on TEXT NOT NULL REFERENCES tasks(id),PRIMARY KEY(task_id,depends_on));
CREATE TABLE checkpoints(application_id TEXT PRIMARY KEY REFERENCES applications(id),payload TEXT NOT NULL CHECK(json_valid(payload)),updated REAL NOT NULL);
CREATE TABLE field_manifests(id TEXT PRIMARY KEY,application_id TEXT NOT NULL REFERENCES applications(id),payload TEXT NOT NULL CHECK(json_valid(payload)),created REAL NOT NULL);
CREATE TABLE answer_versions(id TEXT PRIMARY KEY,application_id TEXT REFERENCES applications(id),profile_version TEXT NOT NULL REFERENCES profile_versions(id),question TEXT NOT NULL,scope TEXT NOT NULL CHECK(json_valid(scope)),answer TEXT NOT NULL,approved INTEGER NOT NULL CHECK(approved IN (0,1)),created REAL NOT NULL);
CREATE TABLE validations(id TEXT PRIMARY KEY,application_id TEXT NOT NULL REFERENCES applications(id),snapshot TEXT NOT NULL CHECK(json_valid(snapshot)),created REAL NOT NULL);
CREATE TABLE upload_evidence(id TEXT PRIMARY KEY,application_id TEXT NOT NULL REFERENCES applications(id),document_id TEXT NOT NULL REFERENCES documents(id),evidence TEXT NOT NULL CHECK(json_valid(evidence)),created REAL NOT NULL);
CREATE TABLE missing_questions(id TEXT PRIMARY KEY,application_id TEXT NOT NULL REFERENCES applications(id),question_key TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),resolved INTEGER NOT NULL DEFAULT 0 CHECK(resolved IN (0,1)),UNIQUE(application_id,question_key));
CREATE TABLE submission_attempts(id TEXT PRIMARY KEY,application_id TEXT NOT NULL REFERENCES applications(id),run_id TEXT NOT NULL REFERENCES runs(id),state TEXT NOT NULL CHECK(state IN ('INTENT','UNCONFIRMED','CONFIRMED')),snapshot TEXT NOT NULL CHECK(json_valid(snapshot)),created REAL NOT NULL);
CREATE UNIQUE INDEX unresolved_submission ON submission_attempts(application_id) WHERE state IN ('INTENT','UNCONFIRMED');
CREATE TABLE receipts(id TEXT PRIMARY KEY,attempt_id TEXT REFERENCES submission_attempts(id),application_id TEXT NOT NULL REFERENCES applications(id),source TEXT NOT NULL,reference TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),created REAL NOT NULL);
CREATE TABLE events(id INTEGER PRIMARY KEY AUTOINCREMENT,application_id TEXT REFERENCES applications(id),kind TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),created REAL NOT NULL);
CREATE TRIGGER immutable_events_update BEFORE UPDATE ON events BEGIN SELECT RAISE(ABORT,'events are append only'); END;
CREATE TRIGGER immutable_events_delete BEFORE DELETE ON events BEGIN SELECT RAISE(ABORT,'events are append only'); END;
CREATE TABLE cache_entries(key TEXT PRIMARY KEY,kind TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),expires REAL NOT NULL,size INTEGER NOT NULL CHECK(size>=0),accessed REAL NOT NULL);
CREATE TABLE portal_accounts(id TEXT PRIMARY KEY,employer TEXT NOT NULL,origin TEXT NOT NULL,email TEXT NOT NULL,secret_ref TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('PENDING','USABLE','RECONNECT')),UNIQUE(employer,origin,email));
CREATE TABLE mail_connections(id TEXT PRIMARY KEY,email TEXT NOT NULL,scopes TEXT NOT NULL CHECK(json_valid(scopes)),secret_ref TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('CONNECTED','DISCONNECTED','RECONNECT')));
CREATE TABLE email_transactions(id TEXT PRIMARY KEY,application_id TEXT NOT NULL REFERENCES applications(id),account_id TEXT REFERENCES portal_accounts(id),mailbox TEXT NOT NULL,recipient TEXT NOT NULL,tenant TEXT NOT NULL,action TEXT NOT NULL,requested REAL NOT NULL,expires REAL NOT NULL,rules TEXT NOT NULL CHECK(json_valid(rules)),status TEXT NOT NULL CHECK(status IN ('PENDING','CONSUMING','CONSUMED','UNCONFIRMED','EXPIRED')),message_id TEXT UNIQUE);
CREATE TABLE adapter_qualifications(adapter TEXT NOT NULL,workflow TEXT NOT NULL,level TEXT NOT NULL CHECK(level IN ('IMPLEMENTED','SYNTHETIC','SUPERVISED','UNATTENDED')),evidence TEXT NOT NULL,PRIMARY KEY(adapter,workflow,level));
CREATE TABLE legacy_imports(id TEXT PRIMARY KEY,source_hash TEXT NOT NULL UNIQUE,payload TEXT NOT NULL CHECK(json_valid(payload)),created REAL NOT NULL);
